<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/db.php';
requireRole(['administrator']);
$conn = db();
$residents = $conn->query("SELECT a.id AS allocation_id, u.id AS student_id, u.username, u.email, u.created_at,
    sp.student_number, sp.phone, sp.course, sp.year_of_study, r.id AS room_id, r.room_number,
    r.room_type, h.name AS hostel_name, a.allocated_at
    FROM room_allocations a JOIN users u ON u.id = a.student_id
    JOIN rooms r ON r.id = a.room_id JOIN hostel_profiles h ON h.id = r.hostel_id
    LEFT JOIN student_profiles sp ON sp.user_id = u.id
    WHERE a.status = 'active' ORDER BY h.name, r.room_number, u.username")->fetch_all(MYSQLI_ASSOC);
$unassigned = $conn->query("SELECT u.id, u.username FROM users u LEFT JOIN room_allocations a ON a.student_id=u.id AND a.status='active' WHERE u.role='student' AND u.status='active' AND a.id IS NULL ORDER BY u.username")->fetch_all(MYSQLI_ASSOC);
$rooms = $conn->query("SELECT r.id, r.room_number, r.capacity, r.occupied, h.name AS hostel_name FROM rooms r JOIN hostel_profiles h ON h.id=r.hostel_id WHERE r.status <> 'maintenance' AND r.occupied < r.capacity ORDER BY h.name,r.room_number")->fetch_all(MYSQLI_ASSOC);
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Residents | CourtIQ</title><link rel="stylesheet" href="<?= projectUrl('assets/css/style.css') ?>"></head>
<body class="dashboard-layout admin-dashboard"><?php require __DIR__ . '/partials/nav.php'; ?><main class="dashboard-content-main container admin-main">
<?php if (!empty($_GET['error'])): ?><div class="admin-alert is-error"><?= e($_GET['error']) ?></div><?php endif; ?><?php if (!empty($_GET['success'])): ?><div class="admin-alert is-success">Resident records saved.</div><?php endif; ?>
<section class="admin-page-heading"><div><span class="admin-eyebrow">RESIDENT DIRECTORY</span><h1>Residents &amp; room assignments</h1><p>Every active resident, their student details and current room assignment.</p></div><a class="btn btn-primary" href="manage.php">Manage student accounts</a></section>
<section class="admin-section"><div class="admin-section-heading"><div><h2>All residents</h2><p>Reassign or remove a resident directly from the table.</p></div><span class="admin-count"><?= count($residents) ?> allocated</span></div><div class="admin-table-wrap"><table class="dash-table admin-table resident-table"><thead><tr><th>Student details</th><th>Hostel &amp; room</th><th>Reassign</th><th>Remove</th></tr></thead><tbody><?php foreach ($residents as $resident): ?><tr><td><strong><?= e($resident['username']) ?></strong><small><?= e($resident['email']) ?></small><small><?= e($resident['student_number'] ?: 'Student number not added') ?> · <?= e($resident['course'] ?: 'Course not added') ?></small><small><?= e($resident['phone'] ?: 'Phone not added') ?><?= $resident['year_of_study'] ? ' · Year ' . (int)$resident['year_of_study'] : '' ?></small></td><td><span class="room-chip"><?= e($resident['hostel_name']) ?> · <?= e($resident['room_number']) ?></span><small><?= e($resident['room_type']) ?></small><small>Allocated <?= date('M j, Y', strtotime($resident['allocated_at'])) ?></small></td><td><form method="post" action="actions.php" class="inline-form"><?= csrfField() ?><input type="hidden" name="action" value="allocation_save"><input type="hidden" name="student_id" value="<?= (int)$resident['student_id'] ?>"><select name="room_id"><option value="<?= (int)$resident['room_id'] ?>">Keep current</option><?php foreach ($rooms as $room): ?><option value="<?= (int)$room['id'] ?>"><?= e($room['hostel_name']) ?> · <?= e($room['room_number']) ?> (<?= (int)$room['capacity']-(int)$room['occupied'] ?> free)</option><?php endforeach; ?></select><button class="btn btn-primary btn-sm">Save</button></form></td><td><form method="post" action="actions.php" onsubmit="return confirm('Remove this resident from the room?');"><?= csrfField() ?><input type="hidden" name="action" value="allocation_end"><input type="hidden" name="allocation_id" value="<?= (int)$resident['allocation_id'] ?>"><button class="btn btn-danger btn-sm">Remove</button></form></td></tr><?php endforeach; ?><?php if (!$residents): ?><tr><td colspan="4" class="admin-empty">No active residents have been allocated.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="admin-section"><div class="admin-section-heading"><div><span class="admin-eyebrow">NEW ASSIGNMENT</span><h2>Assign an unallocated student</h2></div></div><form method="post" action="actions.php" class="admin-form"><?= csrfField() ?><input type="hidden" name="action" value="allocation_save"><select name="student_id" required><option value="">Select student</option><?php foreach ($unassigned as $student): ?><option value="<?= (int)$student['id'] ?>"><?= e($student['username']) ?></option><?php endforeach; ?></select><select name="room_id" required><option value="">Select available room</option><?php foreach ($rooms as $room): ?><option value="<?= (int)$room['id'] ?>"><?= e($room['hostel_name']) ?> · <?= e($room['room_number']) ?> (<?= (int)$room['capacity']-(int)$room['occupied'] ?> free)</option><?php endforeach; ?></select><button class="btn btn-primary">Assign resident</button></form></section>
</main></body></html>
